import json, random, math

with open\('pirates.json'\) as f:
    pdata = json.load\(f\)

course_names = list\(pdata['courses'].keys\(\)\)
course_idx = {name: i for i, name in enumerate\(course_names\)}

pirates = []
for p in pdata['pirates']:
    favs = set\(\)
    for cat in p['favorites']:
        for cname, cats in pdata['courses'].items\(\):
            if cat in cats: favs.add\(course_idx[cname]\)
    allergies = set\(\)
    for cat in p['allergies']:
        for cname, cats in pdata['courses'].items\(\):
            if cat in cats: allergies.add\(course_idx[cname]\)
    pirates.append\({'name': p['name'], 'strength': p['strength'], 'weight': p['weight'], 'favs': favs, 'allergies': allergies}\)

with open\('historical_matches.json'\) as f:
    days = json.load\(f\)

pirate_idx = {p['name']: i for i, p in enumerate\(pirates\)}
max_weight, max_effect, base, fav_pct, zv_bonus = 221, 10, 103, 91, 8

def wo\(w\):
    if w >= max_weight: return 0
    return min\(\(max_weight - w\) // 2, max_effect\)

def sc\(pi, courses, rng\):
    p = pirates[pi]
    na = sum\(1 for c in courses if c in p['allergies']\)
    nf = sum\(1 for c in courses if c in p['favs'] and c not in p['allergies']\)
    w = wo\(p['weight']\)
    life = p['strength']
    for _ in range\(na\):
        if w > 0: life -= rng.randint\(1, w\)
    if nf == 0 and na == 0 and zv_bonus > 0: life += rng.randint\(1, zv_bonus\)
    upper = max\(1, int\(max\(1.0, max\(1, base - life\) * \(fav_pct/100\)**nf\)\)\)
    return -\(rng.randint\(1,upper\) + rng.randint\(1,upper\) + rng.randint\(1,upper\)\)

n_days = len\(days\)
split = int\(n_days * 0.8\)
rng = random.Random\(42\)
total_ll = 0
n = 0
SIMS = 500
for day in days[split:]:
