        pis = [pirate_idx[p['name']] for p in arena['pirates']]
        courses = [course_idx[f] for f in arena['foods'] if f in course_idx]
        wp = next\(i for i, p in enumerate\(arena['pirates']\) if p['name'] == arena['winner']\)
        wins = [0]*4
        for _ in range\(SIMS\):
            scores = [sc\(pis[i], courses, rng\) for i in range\(4\)]
            mx = max\(scores\)
            tied = [i for i in range\(4\) if scores[i] == mx]
            wins[rng.choice\(tied\)] += 1
        total_ll += math.log\(max\(wins[wp] / SIMS, 1e-6\)\)
        n += 1
print\(f'H19 baseline \(test\): ll={total_ll/n:.4f}  uniform={math.log\(0.25\):.4f}  n={n}'\)
